const bareWelcomeCheckoutScript='<script type="module" id="bare-welcome-checkout-script">import{createClient}from"https://cdn.jsdelivr.net/npm/@supabase/supabase-js/+esm";const sb=createClient("https://adltmckypuqwzbcuvuuh.supabase.co","sb_publishable_ZDEvoNTASICy-Z2hqqTOGA_EHFz2Yv1"),money=value=>"₩"+Number(value||0).toLocaleString("ko-KR"),read=key=>{try{return JSON.parse(localStorage.getItem(key)||"[]")}catch{return[]}},items=read("bare_checkout_items").length?read("bare_checkout_items"):read("bare_cart_items"),subtotal=items.reduce((sum,item)=>sum+Number(item.price||0),0);localStorage.removeItem("bare_selected_coupon");let eligible=false;try{const{data}=await sb.auth.getSession(),session=data?.session;if(session){const response=await fetch("/api/customer/orders?welcome="+Date.now(),{headers:{Authorization:"Bearer "+session.access_token},cache:"no-store"}),result=await response.json();eligible=response.ok&&Array.isArray(result.orders)&&result.orders.length===0}}catch(error){console.warn("welcome eligibility",error)}localStorage.setItem("bare_welcome_pack_eligible",eligible?"1":"0");const single=["#I\\u0027M BARED halter top","#I\\u0027M BARED high-up leggings","T-libbed sleeveless"],baseShipping=items.length&&items.every(item=>single.includes(item.title))?3000:0,shipping=eligible?0:baseShipping,discount=eligible?Math.round(subtotal*.1):0,total=Math.max(0,subtotal+shipping-discount),section=document.querySelector("#discount-line")?.closest(".section-body");section?.querySelectorAll(".coupon-row,.coupon-select-row,.coupon-hint").forEach(item=>item.remove());if(section&&!section.querySelector(".welcome-checkout-benefit"))section.insertAdjacentHTML("afterbegin","<div class=\\"welcome-checkout-benefit "+(eligible?"":"is-locked")+"\\"><span>WELCOME PACK</span><strong>"+(eligible?"10% 할인 + 무료배송":"신규회원 첫 구매 전용")+"</strong></div><p class=\\"welcome-checkout-note\\">"+(eligible?"자동 적용되었습니다.":"로그인한 신규회원에게 자동 적용됩니다.")+"</p>");const set=(id,text)=>{const el=document.getElementById(id);if(el)el.textContent=text};set("shipping",money(shipping));set("discount-line","-"+money(discount));set("discount-total","-"+money(discount));set("summary-discount","-"+money(discount));set("grand-total",money(total));set("points",money(0)+"원");const pay=document.getElementById("pay-button");if(pay)pay.textContent=money(total)+" 결제하기";</script>';
